css:
.fr { display:inline-flex; flex-direction:column; align-items:stretch; text-align:center;
      line-height:1.14;
      vertical-align:middle; font-size:.86em; font-family:'Times New Roman',Times,serif; font-style:italic; }

/* A paper reference — `2025/set_jv`. Plain text in the body face, so
   it reads as a citation rather than as an expression. */
.ref { font-family:inherit; font-style:normal;
       color:#6b6656; white-space:nowrap; }

/* A unit written as a fraction in ordinary prose — `न्यूटन` over
   `ऐम्पियर·मीटर`. It keeps the BODY face, upright: it is a unit name,
   not an algebraic operand, and the maths italic made it read as a
   formula dropped into the middle of a Devanagari sentence. */
.fr-unit { font-family:inherit; font-style:normal;
           font-size:0.95em; }
.fr-unit > span, .fr-unit > .dn { font-style:normal; }

/* A FRACTION INSIDE A FRACTION.
   `.fr` is already .86em, so two levels compound to .74 and three
   to .64 — small enough that a nested denominator stops being
   readable in print. An inner level takes a gentler step down and
   keeps the rule it needs to read as a fraction at all. */
.fr .fr { font-size:.94em; }
.fr>.dn { border-top:1.1px solid currentColor; margin-top:1px;
          padding-top:1px; }
/* The nested case needs a touch more room, or the inner rule and
   the outer one sit on top of each other. */
.fr .fr>.dn { margin-top:2px; padding-top:1px; }
.fr:has(.fr)>span { padding:1px 3px; }
